// Chapter 5 (second half) cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch5).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['linas-voice', ["Dutch has the diary open on his knee", "She built her own on top of mine", "Give it here"]],
    ['linas-voice-dawn', ["By morning Seo-yeon has it", "Don't do her voice", "I'm not. I don't know it"]],
    ['the-ledgers', ["Under the closet's last shelf", "Freya copies everything and reads nothing", "A column of names from twenty-five years ago", "I washed out", "something flickers in his hands"]],
    ['the-button', ["turning a button over and over", "You've been turning that thing over", "Caspian's collar", "She takes it, and looks at it", "You can't know that", "He goes outside, and doesn't come back"]],
    ['a-deal', ["A deal. I'll give you Iris", "Dutch doesn't answer for a long time", "No, the other chair", "It wobbles"]],
    ['backoff', ["Kai and Dutch both go for it first", "In my old job", "Exponential backoff with jitter", "Bless you"]],
    ['turned-on', ["Seo-yeon finds Dutch by the fire", "You're keeping a log", "Lina turned a ward on a week before", "Like data events", "He hands her the pencil", "She taps three, one, four"]],
    ['the-record', ["The Observatory, floor 80. 23:50", "I visited a sick girl with flowers", "I'm not going to tell you what I'm sure of"]],
    ['the-record-ev1', ["A third of the lanterns go out along the walls"]],
    ['the-record-ev2', ["Another third go out"]],
    ['the-record-dark', ["The last lanterns go out"]],
    ['the-shift', ["At 100% her version is gone", "Pa did everything at midnight", "Freya's pipeline breaks for good"]],
    ['the-rail', ["The real Astronomy Tower, on the town floor", "You won't. You didn't then"]],
    ['the-rail-hold', ["pulls Iris up out of his hands", "Lord Ashgrove has followed him", "Your boy grabbed for her hand", "calls off the watch"]],
    ['the-rail-let', ["He lets go. Freya", "Lord Ashgrove has followed him", "Your boy grabbed for her hand", "calls off the watch"]],
    ['she-nearly-did', ["Uptima reads the prayer: \"Let her wake", "healers' chart with him", "She was coming back. She nearly did", "That's not better"]],
    ['the-lanterns-go-out', ["The students' lanterns go out across the band", "They come down to the camp"]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
